import sys

class InputReader:
    def __init__(self, stream):
        self.reader = stream
        self.tokens = []

    def next(self):
        while not self.tokens:
            line = self.reader.readline()
            if not line:
                raise Exception("End of input")
            self.tokens = line.strip().split()
        return self.tokens.pop(0)

    def nextInt(self):
        return int(self.next())

def main():
    in_stream = sys.stdin
    out_stream = sys.stdout
    in_reader = InputReader(in_stream)
    # Read inputs
    w = in_reader.nextInt()
    m = in_reader.nextInt()
    n = 0
    a = [0] * 50
    # Convert m to base w
    while True:
        n += 1
        a[n] = m % w
        m //= w
        if m == 0:
            break
    ok = True
    i = 1
    while i <= n:
        if a[i] > 1:
            a[i] += 1
            if a[i] == w:
                while i <= n and a[i] >= w:
                    a[i] = 0
                    i += 1
                    if i > n:
                        n += 1
                        a.append(0)
                    a[i] += 1
            else:
                i += 1
            if a[i - 1] > 1:
                ok = False
                break
        else:
            i += 1
    if ok:
        print("YES", file=out_stream)
    else:
        print("NO", file=out_stream)

if __name__ == "__main__":
    main()

